import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"发布流程（SOP）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/process.md","filePath":"zh/release/process.md"}'),i={name:"zh/release/process.md"};function d(n,e,l,c,p,r){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="发布流程-sop" tabindex="-1">发布流程（SOP） <a class="header-anchor" href="#发布流程-sop" aria-label="Permalink to &quot;发布流程（SOP）&quot;">​</a></h1><p>一次发布走过的确切序列。每一步都有门禁；门禁失败即停止 发布。</p><h2 id="_0-预检" tabindex="-1">0. 预检 <a class="header-anchor" href="#_0-预检" aria-label="Permalink to &quot;0. 预检&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git fetch &amp;&amp; git status        (clean tree, correct branch)</span></span>
<span class="line"><span>git tag --list &#39;v*&#39;           (the new tag does not exist yet)</span></span>
<span class="line"><span>git config user.name / user.email   (author = cubestudio-dev &lt;cubestudio@qq.com&gt;)</span></span></code></pre></div><h2 id="_1-构建" tabindex="-1">1. 构建 <a class="header-anchor" href="#_1-构建" aria-label="Permalink to &quot;1. 构建&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make clean &amp;&amp; make -j$(nproc) all</span></span></code></pre></div><p>门禁：0 错误 0 警告（<code>-Wall -Wextra -Werror</code> 在参数里） <strong>本地工具链和 GitHub Actions runner 两边都要满足</strong>——2.0.0 发布过本地能编译、CI 上不能的源码（tui_core.c 端口约束 P0； 见 KNOWN_ISSUES.md）。CI 绿是硬发布门禁，不是锦上添花。 产物：<code>build/opencube.iso</code>、<code>dist/OpenCubeOS-&lt;ver&gt;-src.zip</code>、 <code>dist/OpenCubeOS-&lt;ver&gt;-update.tar.gz</code>。</p><h2 id="_2-可复现性" tabindex="-1">2. 可复现性 <a class="header-anchor" href="#_2-可复现性" aria-label="Permalink to &quot;2. 可复现性&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make reproducible-check</span></span></code></pre></div><p>门禁：<code>PASS - ELF byte-identical across two clean builds</code>。</p><h2 id="_3-启动门禁" tabindex="-1">3. 启动门禁 <a class="header-anchor" href="#_3-启动门禁" aria-label="Permalink to &quot;3. 启动门禁&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios      (banner + ring-3 ush&gt; + boot complete)</span></span>
<span class="line"><span>make run-uefi      (same, through OVMF)</span></span></code></pre></div><p>默认启动落进 Ring-3 的 <code>ush&gt;</code> shell；2.x 的 <code>oc&gt;</code> 提示符在 <code>exit</code> 之后出现（或启动器失败时出现——恢复姿态）。</p><h2 id="_4-深度测试门禁-针对构建出的-iso" tabindex="-1">4. 深度测试门禁（针对构建出的 ISO） <a class="header-anchor" href="#_4-深度测试门禁-针对构建出的-iso" aria-label="Permalink to &quot;4. 深度测试门禁（针对构建出的 ISO）&quot;">​</a></h2><p>2.1.0 验证矩阵——每个套件都在串口控制台上驱动一次真实的 QEMU 启动；把真实输出（含声明的跳过计数）贴进发布证据：</p><table tabindex="0"><thead><tr><th>门禁</th><th>命令</th><th>证明什么</th></tr></thead><tbody><tr><td>宿主机单元测试</td><td><code>make test</code></td><td>17 个测试桩 PASS（无 openssl 夹具时 +2 SKIP-FIXTURE——声明跳过）</td></tr><tr><td>看门狗/日志/健康 E2E</td><td><code>tools/wp12_watchdog_logging_e2e.py</code></td><td>14 个场景（S1-S14，含 Intel TCO 真实复位）</td></tr><tr><td>TUI 命令面 E2E</td><td><code>tools/wp10_tui_e2e.py</code></td><td>v2 启动流上的 L0 TUI 命令</td></tr><tr><td>中文控制台 E2E</td><td><code>tools/wp10_chinese_e2e.py</code></td><td>CJK 层端到端</td></tr><tr><td>TUI 桌面应用 E2E</td><td><code>tools/wp10_tuiqa_apps_e2e.py</code></td><td>从 <code>ush&gt;</code> 出发的桌面五应用流</td></tr><tr><td>原生桌面 E2E</td><td><code>tools/wp10_native_e2e.py</code></td><td>原生编辑器/文件管理器流程</td></tr><tr><td>L1 逐应用记录</td><td>从 ush 经 <code>run</code> 运行每个 <code>l1apps/</code> 程序</td><td>ush + 每个内嵌程序真实执行（2.1.0 新增；见 docs/dev/e2e-suites.md）</td></tr></tbody></table><h2 id="_5-打-tag-发布" tabindex="-1">5. 打 tag + 发布 <a class="header-anchor" href="#_5-打-tag-发布" aria-label="Permalink to &quot;5. 打 tag + 发布&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git tag -a v&lt;version&gt;          # ONLY on a CI-green commit</span></span>
<span class="line"><span>git push origin main --tags</span></span></code></pre></div><p>从该 tag 创建 GitHub Release，说明中包含：变更摘要、 新接口、已知问题、三个 SHA256。附上三个资产。发布脚本 （<code>tools/build_release.sh --deep</code>）自动完成清单 + 说明 + 上传。</p><p><strong>发布门禁（2.1.0）：tag 必须指向 CI 绿的提交。 绝不给红色提交打 tag。</strong></p><h2 id="_6-网站-wiki" tabindex="-1">6. 网站 + wiki <a class="header-anchor" href="#_6-网站-wiki" aria-label="Permalink to &quot;6. 网站 + wiki&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tools/update_website.sh    (versions/hashes/downloads on the site)</span></span>
<span class="line"><span>tools/sync_wiki.sh         (docs/ -&gt; the GitHub Wiki)</span></span></code></pre></div><p>门禁：线上站点显示新版本，三个 SHA256 与 Release 一致， 下载解析为 HTTP 200 且哈希校验通过，且站点统计块从 <code>docs/data/*.json</code> 重新生成（绝不从过期块复制——2.0.0 的 站点就这样带着过期的 130,011 行数上线过）。</p><h2 id="_7-私有镜像" tabindex="-1">7. 私有镜像 <a class="header-anchor" href="#_7-私有镜像" aria-label="Permalink to &quot;7. 私有镜像&quot;">​</a></h2><p>把三个资产 + 发布说明 + 镜像的网站文件复制进私有仓库 （<code>oc-os/</code> 树 + 仓库级审计文档）；推送。门禁：两个仓库的 <code>git ls-remote</code> 都显示预期的 HEAD。</p><h2 id="_8-十二点检查" tabindex="-1">8. 十二点检查 <a class="header-anchor" href="#_8-十二点检查" aria-label="Permalink to &quot;8. 十二点检查&quot;">​</a></h2><ol><li>两个仓库的远端 HEAD 与本地一致。</li><li>tag 存在于公开仓库且指向 CI 绿的提交。</li><li>每个发布提交都有作者身份。</li><li>gh-pages 已更新（线上站点服务新版本）。</li><li>update.json：version + build + package_sha256（两份 副本——website/ 顶层 AND website/public/——逐字节一致）。</li><li>三方资产哈希：本地 = Release API 摘要 = 线上 下载。</li><li>网站数字（命令/接口/行数）与 <code>docs/data/*.json</code> 一致（重新生成，而非复制）。</li><li>第 4 步的门禁全绿（贴出输出，声明 跳过计数）。</li><li>令牌卫生（只显示过末四位）。</li><li>全仓数字一致性：251 个命令归属（99+133+19）/ 17 个类别 / 158 个 L1SVC 操作 / 54 个系统调用 / 当前的 stats.json 行数（每次发布重新计算；绝不用过期 数字）。</li><li>私有镜像完整。</li><li>发布提交（以及打 tag 的提交）CI 绿。</li></ol><h2 id="_9-报告" tabindex="-1">9. 报告 <a class="header-anchor" href="#_9-报告" aria-label="Permalink to &quot;9. 报告&quot;">​</a></h2><p>交付报告引用：构建证据（本地 + CI）、全部门禁 输出、推送输出（公开 + 私有）、Release URL、站点 URL、三个 SHA256，以及诚实偏差清单。</p>`,29)])])}const g=a(i,[["render",d]]);export{u as __pageData,g as default};
